import{_ as s,o as p,c as e,a2 as t}from"./chunks/framework.EUByU7Iq.js";const i=JSON.parse('{"title":"远逝","description":"","frontmatter":{"title":"远逝","date":"2026-11-24T00:00:00.000Z","seq":51,"categories":["美文","楚辞"],"collection":"《楚辞》","tags":["楚辞","先秦"],"poem":true,"poem_quote":false,"author":"刘向","source_book":"楚辞","prev":{"text":"九叹·怨思","link":"/blogs/楚辞/九叹·怨思.html"},"next":{"text":"惜贤","link":"/blogs/楚辞/惜贤.html"}},"headers":[],"relativePath":"blogs/楚辞/远逝.md","filePath":"blogs/楚辞/远逝.md"}'),o={name:"blogs/楚辞/远逝.md"};function l(n,a,c,m,z,r){return p(),e("div",null,[...a[0]||(a[0]=[t('<h1 id="远逝" tabindex="-1">远逝 <a class="header-anchor" href="#远逝" aria-label="Permalink to &quot;远逝&quot;">​</a></h1><p class="poem-meta">先秦 · 刘向　·　九叹</p><div class="poem"><p class="poem-stanza">志隐隐而郁怫兮，愁独哀而冤结。</p><p class="poem-stanza">肠纷纭以缭转兮，涕渐渐其若屑。</p><p class="poem-stanza">情慨慨而长怀兮，信上皇而质正。</p><p class="poem-stanza">合五岳与八灵兮，讯九鬿与六神。</p><p class="poem-stanza">指列宿以白情兮，诉五帝以置辞。</p><p class="poem-stanza">北斗为我折中兮，太一为余听之。</p><p class="poem-stanza">云服阴阳之正道兮，御后土之中和。</p><p class="poem-stanza">佩苍龙之蚴虬兮，带隐虹之逶蛇。</p><p class="poem-stanza">曳彗星之皓旰兮，抚朱爵与鵔鸃。</p><p class="poem-stanza">游清灵之飒戾兮，服云衣之披披。</p><p class="poem-stanza">杖玉策与朱旗兮，垂明月之玄珠。</p><p class="poem-stanza">举霓旌之墆翳兮，建黄纁之总旄。</p><p class="poem-stanza">躬纯粹而罔愆兮，承皇考之妙仪。</p><p class="poem-stanza">惜往事之不合兮，横汨罗而下沥。</p><p class="poem-stanza">乘隆波而南渡兮，逐江湘之顺流。</p><p class="poem-stanza">赴阳侯之潢洋兮，下石濑而登洲。</p><p class="poem-stanza">陆魁堆以蔽视兮，云冥冥而闇前。</p><p class="poem-stanza">山峻高以无垠兮，遂曾闳而迫身。</p><p class="poem-stanza">雪雰雰而薄木兮，云霏霏而陨集。</p><p class="poem-stanza">阜隘狭而幽险兮，石嵾嵯以翳日。</p><p class="poem-stanza">悲故乡而发忿兮，去余邦之弥久。</p><p class="poem-stanza">背龙门而入河兮，登大坟而望夏首。</p><p class="poem-stanza">横舟航而济湘兮，耳聊啾而戃慌。</p><p class="poem-stanza">波淫淫而周流兮，鸿溶溢而滔荡。</p><p class="poem-stanza">路曼曼其无端兮，周容容而无识。</p><p class="poem-stanza">引日月以指极兮，少须臾而释思。</p><p class="poem-stanza">水波远以冥冥兮，眇不睹其东西。</p><p class="poem-stanza">顺风波以南北兮，雾宵晦以纷纷。</p><p class="poem-stanza">日杳杳以西颓兮，路长远而窘迫。</p><p class="poem-stanza">欲酌醴以娱忧兮，蹇骚骚而不释。</p><p class="poem-stanza">叹曰：</p><p class="poem-stanza">飘风蓬龙埃坲々兮，草木摇落时槁悴兮，</p><p class="poem-stanza">遭倾遇祸不可救兮，长吟永欷涕究究兮，</p><p class="poem-stanza">舒情陈诗冀以自免兮，颓流下陨身日远兮。</p></div>',3)])])}const d=s(o,[["render",l]]);export{i as __pageData,d as default};
